'use strict';
const fs = require('fs');
const path = require('path');
const DIR = path.join(__dirname, '..', 'datasets', 'problems');
const S = {
  python: "import sys\ninput = sys.stdin.readline\ndef solve():\n    pass\nsolve()",
  javascript: "const lines = require('fs').readFileSync('/dev/stdin','utf8').trim().split('\\n');\n// code",
  java: "import java.util.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n    }\n}",
  cpp: "#include<bits/stdc++.h>\nusing namespace std;\nint main(){\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n    return 0;\n}"
};
function merge(file, probs) {
  const fp = path.join(DIR, file);
  let ex = [];
  if (fs.existsSync(fp)) try { ex = JSON.parse(fs.readFileSync(fp, 'utf8')); } catch(e) {}
  const slugs = new Set(ex.map(p => p.slug));
  const add = probs.filter(p => !slugs.has(p.slug));
  fs.writeFileSync(fp, JSON.stringify([...ex, ...add], null, 2));
  console.log(`${file}: +${add.length} = ${ex.length + add.length}`);
  return add.length;
}

